 */
public class Reporter_noMoreInteractionsWanted_TriageGen1Test {

    @Test
    public void testNoMoreInteractionsWantedThrowsExceptionWithCorrectMessage() {
        // Arrange
        Reporter reporter = new Reporter();

        // Mock the undesired invocation
        Invocation undesired = mock(Invocation.class);
        Object mockObject = new Object();
        Location undesiredLocation = mock(Location.class);

        // Setup the return values for the undesired invocation
        // We use a mock for Location to ensure it has a non-null/predictable behavior if needed, 
        // but here we just need it to return something for the string concatenation.
        org.mockito.internal.stubbing.verification.Location mockLocation = mock(org.mockito.internal.stubbing.verification.Location.class);

        // Using the actual class implementation for Location if possible or mocking it
        // Since Location is an interface/class used in the method
        org.mockito.internal.stubbing.verification.Location location = new org.mockito.internal.stubbing.verification.LocationImpl();

        // In a real scenario, undesired.getMock() returns the mock object
        // and undesired.getLocation() returns the location.
        // We must ensure these don't throw NullPointerException during the string concatenation.
        org.mockito.internal.invocation.Invocation undesiredInvocation = mock(org.mockito.internal.invocation.Invocation.class);
        org.mockito.internal.stubbing.verification.Location undesiredLocationImpl = new org.mockito.internal.stubbing.verification.LocationImpl();

        // We need to mock the behavior of the parameters passed to the method
        // Note: Invocation here is org.mockito.invocation.Invocation
        // But the method signature uses org.mockito.invocation.Invocation
        // In Mockito internals, Invocation is often an interface.

        // Re-defining mocks to match the method signature requirements
        Invocation mockUndesired = mock(Invocation.class);
        org.mockito.internal.stubbing.verification.Location mockUndesiredLocation = new org.mockito.internal.stubbing.verification.LocationImpl();

        // We need to simulate the behavior of the parameters
        // Since we cannot easily mock the 'join' or 'ScenarioPrinter' if they are final/static,
        // we rely on the fact that they are instantiated inside the method.

        // Because we can't mock 'new ScenarioPrinter()', we provide valid objects.
        List<VerificationAwareInvocation> invocations = Collections.emptyList();

        // We need to ensure undesired.getMock() and undesired.getLocation() are not null 
        // to avoid NPE before the NoInteractionsWanted exception is thrown.
        // However, the method calls undesired.getMock() and undesired.getLocation().
        // Let's use a real mock for the undesired parameter.

        // We'll use a custom approach to avoid stubbing issues with deep mocks
        Invocation undesiredMock = new Invocation() {
            @Override
            public Object getMock() {
                return "someMock";
            }

            @Override
            public Object getInvocation() {
                return null;
            }

            @Override
            public Location getLocation() {
                return new org.mockito.internal.stubbing.verification.LocationImpl();
            }

            @Override
            public Object[] getArguments() {
                return new Object[0];
            }
        };

        // Act & Assert
        try {
            reporter.noMoreInteractionsWanted(undesiredMock, invocations);
            org.junit.Assert.fail("Expected NoInteractionsWanted exception to be thrown");
        } catch (NoInteractionsWanted e) {
            String message = e.getMessage();
            assertTrue("Message should contain 'No interactions wanted here:'", message.contains("No interactions wanted here:"));
            assertTrue("Message should contain mock name", message.contains("someMock"));
            assertTrue("Message should contain 'But found this interaction on mock'", message.contains("But found this interaction on mock"));
        }
    }

    @Test
    public void testNoMoreInteractionsWantedWithPopulatedInvocations() {
        // Arrange
        Reporter reporter = new Reporter();
        Invocation undesiredMock = new Invocation() {
            @Override
            public Object getMock() { return "mockObj"; }
            @Override
            public Object getInvocation() { return null; }
            @Override
            public Location getLocation() { return new org.mockito.internal.stubbing.verification.LocationImpl(); }
            @Override
            public Object[] getArguments() { return new Object[0]; }
        };

        // Create a list with one invocation to ensure ScenarioPrinter processes it
        // Since VerificationAwareInvocation is an interface used in the list
        VerificationAwareInvocation awarenessInvocation = mock(VerificationAwareInvocation.class);
        List<VerificationAwareInvocation> invocations = Collections.singletonList(awarenessInvocation);

        // Act & Assert
        try {
            reporter.noMoreInteractionsWanted(undesiredMock, invocations);
            org.junit.Assert.fail("Expected NoInteractionsWanted exception");
        } catch (NoInteractionsWanted e) {
            // Success - the exception was thrown. 
            // The content of 'scenario' depends on ScenarioPrinter's implementation.
            assertTrue(e.getMessage().contains("mock 'mockObj'"));
        }
    }
